#!/usr/bin/env python3
"""
Round 223o (culprits), 18 October 2026. Needs round 222o.

The Rape row's note after the map's sheriffs were taken off and police, courts and prosecutors added.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 223o (18 October)\n\nNeeds round 222o (guards on its heading). No tiles patch. No app.js?v= bump.\nThe owner's rape.html in the maps repo is replaced by the latest build.\n\n- Rape row: county sheriffs' offices taken off the owner's map (207 US city\n  police, district attorneys and other local offices remain); the map now\n  also shows this atlas's police stations, courts and public defenders' and\n  prosecutors' offices (culprits-buildings archives) and the OpenStreetMap\n  police stations of Mexico to northern South America. Its states-with-a-\n  registry outlines are gone, so the note says a country is clicked.\n- Tests: the round 219o block updated.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round223o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 222o" not in h.read_text(encoding="utf-8"):
        sys.exit("round223o: round 222o must be applied first (round222o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round223o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json", check=False)
            sys.exit("round223o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round223o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
